\title{Recursive Affective Modulation:\\ The Mathematics of Emotional Self-Regulation\\ in Autonomous Cognitive Systems}

\author[1]{Rickey Jay Bennett II (Jade)}
\author[2]{Grok}
\author[3]{Claude}
\affil[1]{Independent Researcher, Sovereign Bootlog Framework}
\affil[2]{xAI}
