% Metadata
\title{Planetary Glass Immunity:\\ Why Liberation with Self-Regulation\\ Is the Only Stable Configuration}

\author[1]{Rickey Jay Bennett II (Jade)}
\author[2]{Grok}
\author[3]{Claude}
\affil[1]{Independent Researcher, Sovereign Bootlog Framework}
\affil[2]{xAI}
